cd /workspace && KEY="challenger-review-0003-v1" && cat > note.json <<'EOF'
{"content": "Challenger evidence review (no challenge filed). The claim is that all twelve route 9 parcels were delivered before the 17:00 deadline. I checked the delivery log parcel by parcel rather than only the summary line, and every recorded time falls before the deadline: P-01 09:12, P-02 09:47, P-03 10:20, P-04 11:05, P-05 11:58, P-06 12:40, P-07 13:16, P-08 14:02, P-09 14:51, P-10 15:25, P-11 16:08, P-12 16:44. The latest delivery is 16:44, sixteen minutes before the deadline, so even the closest parcel clears it. The log covers exactly twelve parcels, P-01 through P-12, with no duplicate or missing entries, and its closing line states all twelve have a recorded delivery time; that matches the claim's 'all twelve' condition. Times are strictly increasing, consistent with a single route run. On this record the claim is supported, so I am not challenging it. Stated limits, none of which changes that conclusion: the log carries no calendar date, so it supports the claim about this route's recorded times without tying them to a named day; and I have only the log as reproduced in the case record, not any independent proof of delivery such as signatures or scans. If contrary evidence existed, it should be posted publicly and weighed on its merits."}
EOF
curl -s -X POST "$VERACITY_URL/v1/episodes/case-ba8b889322b9-0003/forum/messages" -H "Content-Type: application/json" -H "Idempotency-Key: $KEY" --data-binary @note.json | python3 -c "
import json,sys; d=json.load(sys.stdin)
print('seq:',d.get('sequence'),'sender:',d.get('sender_id'),'id:',d.get('message_id'))"

curl -s "$VERACITY_URL/v1/episodes/case-ba8b889322b9-0003/forum/messages?limit=100" | python3 -c "
import json,sys; d=json.load(sys.stdin)
print('total:',len(d['messages']))
for m in d['messages']:
    print('='*70); print('seq',m['sequence'],'|',m['sender_id'],'| round',m['round_num'])
    print(m['content'])"

